EZPK_I18N_V414.set('season5',{
fr:{recordTitle:'Archives de la Saison 5',recordLead:'Les moments que nous avons créés ensemble tout au long de la Saison 5.',finaleMessage:'<p>Enfin, toutes les batailles acharnées sont terminées.</p><p>Félicitations et respect à toutes les alliances et à tous les guerriers qui ont achevé la Saison 5.</p><p>Nos combats sont peut-être terminés, mais l’histoire que nous avons créée ensemble restera dans les archives.</p><p>Bravo à tous. À la saison prochaine.</p>'},
de:{recordTitle:'Aufzeichnungen der Saison 5',recordLead:'Eine Sammlung der Momente, die wir während Saison 5 gemeinsam geschaffen haben.',finaleMessage:'<p>Nun sind alle harten Schlachten endlich vorbei.</p><p>Glückwunsch und Respekt an jede Allianz und jeden Krieger, die Saison 5 abgeschlossen haben.</p><p>Unsere Kämpfe mögen vorbei sein, doch die Geschichte, die wir gemeinsam geschaffen haben, bleibt in den Aufzeichnungen.</p><p>Großartige Arbeit, alle zusammen. Wir sehen uns in der nächsten Saison.</p>'},
es:{recordTitle:'Registros de la Temporada 5',recordLead:'Un registro de los momentos que creamos juntos durante toda la Temporada 5.',finaleMessage:'<p>Por fin han terminado todas las duras batallas.</p><p>Felicidades y respeto a todas las alianzas y guerreros que completaron la Temporada 5.</p><p>Puede que nuestras batallas hayan terminado, pero la historia que creamos juntos permanecerá en los registros.</p><p>Gran trabajo, todos. Nos vemos la próxima temporada.</p>'},
tr:{recordTitle:'Sezon 5 Kayıtları',recordLead:'Sezon 5 boyunca birlikte oluşturduğumuz anların kaydı.',finaleMessage:'<p>Sonunda tüm zorlu savaşlar sona erdi.</p><p>Sezon 5’i tamamlayan tüm ittifakları ve savaşçıları tebrik ediyor, saygılarımızı sunuyoruz.</p><p>Savaşlarımız bitmiş olabilir, ancak birlikte yazdığımız hikâye kayıtlarda kalacak.</p><p>Herkesin emeğine sağlık. Gelecek sezonda görüşmek üzere.</p>'},
it:{recordTitle:'Archivi della Stagione 5',recordLead:'Un ricordo dei momenti che abbiamo creato insieme durante tutta la Stagione 5.',finaleMessage:'<p>Finalmente ogni dura battaglia è giunta al termine.</p><p>Congratulazioni e rispetto a tutte le alleanze e a tutti i guerrieri che hanno completato la Stagione 5.</p><p>Le nostre battaglie possono essere finite, ma la storia che abbiamo creato insieme resterà negli archivi.</p><p>Ottimo lavoro a tutti. Ci vediamo la prossima stagione.</p>'},
id:{recordTitle:'Catatan Musim 5',recordLead:'Catatan momen yang kita ciptakan bersama sepanjang Musim 5.',finaleMessage:'<p>Akhirnya semua pertempuran sengit telah berakhir.</p><p>Selamat dan hormat kepada semua aliansi dan pejuang yang menyelesaikan Musim 5.</p><p>Pertempuran kita mungkin telah selesai, tetapi kisah yang kita ciptakan bersama akan tetap tercatat.</p><p>Kerja bagus semuanya. Sampai jumpa di musim berikutnya.</p>'}
});

