id:{title:'INFORMASI HERO',lead:'Pilih kartu hero untuk melihat jenis pasukan dan kemampuan utamanya.',quickTitle:'PANDUAN PILIH CEPAT',quick:'Pilih Selwyn untuk formasi Rider, Sebastian untuk Shooter, dan Ella untuk Fighter. Ketiganya memperkuat pasukan utama dan meningkatkan total damage pasukan.',labels:{type:'JENIS HERO',skill:'KEMAMPUAN UTAMA',effect:'EFEK UTAMA',best:'PALING COCOK UNTUK',summary:'RINGKASAN HERO'},heroes:{selwyn:{name:'Selwyn',type:'Hero Rider',card:'Hero Musim 6 yang meningkatkan damage Rider',skill:'Raven Blood Pack',effects:['Meningkatkan damage Rider 10%','Meningkatkan lagi damage semua jenis pasukan'],best:['Pemain yang fokus Rider','Pertempuran ofensif','Ekspansi wilayah dan pengelolaan pasukan'],summary:'Hero Rider Musim 6 yang memperkuat serangan Rider sekaligus meningkatkan damage semua jenis pasukan.',tags:['Rider','Peningkatan Damage','Musim 6']},sebastian:{name:'Sebastian',type:'Hero Shooter',card:'Hero Musim 6 yang meningkatkan damage skill Shooter',skill:'Moonlit Blessing',effects:['Meningkatkan damage skill Shooter 10%','Meningkatkan lagi total damage pasukan'],best:['Pemain yang fokus Shooter','PvP dan daya tembak jarak jauh','Formasi berbasis damage skill'],summary:'Hero Shooter Musim 6 yang meningkatkan damage skill Shooter sekaligus memperkuat daya tembak seluruh pasukan.',tags:['Shooter','Damage Skill','Musim 6']},ella:{name:'Ella',type:'Hero Fighter',card:'Hero Musim 6 yang meningkatkan kekuatan tempur Fighter',skill:'Pasif Tempur Fighter',effects:['Meningkatkan damage Fighter 10%','Meningkatkan lagi total damage pasukan'],best:['Pemain yang fokus Fighter','Garis depan dan pertempuran jarak dekat','Formasi Fighter'],summary:'Hero Fighter Musim 6 yang meningkatkan performa Fighter dan damage seluruh pasukan.',tags:['Fighter','Peningkatan Tempur','Musim 6']}}}
