EZPK_I18N_V414.set('season6Guides',{
fr:{latest:{title:'GUIDE DES RÈGLES DE SAISON · APERÇU DE LA NOUVELLE SAISON',sections:[['Types de territoires',['Avant-postes : relient les territoires du camp et font avancer la ligne de front ; ne produisent pas de Mithril.','Forteresses : objectifs principaux ; produisent du Mithril chaque semaine.','Autels : territoires de grande valeur, disputables à partir de la semaine 6.']],['Conquête des territoires',['Il n’y a plus de cases de capture, valeur d’abri, points de portail ni forteresse au sens ancien.','Progressez dans l’ordre Avant-postes → Forteresses → Autels.','Les offensives et guerres consomment des tentatives.','Fenêtre principale : 12:00–13:00 heure serveur chaque jour, avec fenêtres supplémentaires mardi et jeudi.','Les Autels ouvrent le jeudi de la semaine 6.','Un territoire ne peut pas être abandonné volontairement.','Vous pouvez renforcer les territoires d’une autre alliance du même camp, mais pas attaquer une alliance du même camp.']],['Destruction',['Une forteresse détenue dont la durabilité tombe à zéro est détruite définitivement.','L’attaquant reçoit du Mithril ; la forteresse détruite ne produit plus de récompenses hebdomadaires.','Les ruines ne peuvent pas déclarer de guerre et la zone détruite ne permet pas la téléportation.']],['Nouveaux passages',['Les passages servent uniquement à traverser la carte. Lorsqu’ils sont fermés, aucune troupe ne peut passer.','Lorsqu’ils sont ouverts, tous les membres du camp peuvent passer, sauf aux passages de camp réservés au camp correspondant.','Quand un passage est fermé, les dirigeants ne peuvent pas lancer d’offensive à travers celui-ci.']],['Téléportation',['Les membres d’un même camp peuvent se déplacer vers les territoires capturés par leur camp.','Territoire de votre alliance : 1 Téléporteur d’alliance. Territoire d’une autre alliance du même camp : 1 Téléporteur avancé.','Après une attaque ou une guerre, vous pouvez vous téléporter directement vers la cible lorsque les conditions le permettent.','Les zones spéciales deviennent disponibles selon la progression du contenu.','Impossible de se téléporter vers une forteresse détruite.']]]},rules:{title:'RÈGLES IMPORTANTES DE LA SAISON 6',sections:[['Protection de la tour de guet',['Les tours de guet en territoire allié sont normalement protégées.','Mardi et jeudi de 12:00 à 13:00, cette protection est temporairement désactivée et permet les attaques d’alliances non alliées.','Les attaques restent soumises aux règles d’ouverture et de passage.']],['Case en feu',['Si vous vous téléportez pendant qu’une tour de guet est ciblée par un ralliement, en combat ou à 0 de durabilité, la case d’origine prend feu et la téléportation est bloquée.','Le feu dure 1 minute.','Aucun état « case en feu » dans la zone Temple Contest.']],['Retour du Comptoir commercial',['Les routes commerciales habituelles rouvrent. Capturez les comptoirs, contrôlez les routes et obtenez des récompenses.']],['Temple Contest',['Les dieux ouvrent des temples antiques et les camps s’affrontent pour les contrôler.','La progression de capture détermine le contrôle ; les classements accordent du Mithril.','Les éliminations augmentent la cote du champ de bataille et débloquent des récompenses par palier.','Des coffres de bénédiction sont distribués après l’événement.']],['Relique antique',['L’artefact des Terres d’origine a perdu l’essentiel de sa puissance. Collectez des Runes pour l’améliorer.','Certains niveaux débloquent des Formations ; des héros plus puissants donnent de meilleures statistiques.','La progression de la relique est réinitialisée à la fin de la saison.']]]},buildings:{title:'STRATÉGIE DES BÂTIMENTS DE SAISON',sections:[['Objectif',['Maximiser la production d’Eau sacrée et débloquer les bâtiments le plus tôt possible.']],['Phase 1 · Tout débloquer',['Obélisque toujours prioritaire.','Montez Autel I → 15, II → 15, III → 15, puis débloquez IV.','Ne montez pas un seul autel à 30 avant d’avoir débloqué les suivants. Plus d’autels tôt = plus d’Eau sacrée.']],['Phase 2 · Monter les autels à niveau égal',['16/16/16/16 → 17/17/17/17, etc., jusqu’à 30.','Chaque niveau ajoute +720 Eau sacrée/heure ; une progression équilibrée donne le meilleur rendement global.']],['Priorité Obélisque',['Améliorez l’Obélisque dès que possible : il débloque les niveaux de bâtiments, les nouvelles structures et la progression.']],['Après Obélisque 30',['Priorité : Portail en premier, Sanctuaire ensuite, bâtiments de collecte en dernier.']]]}},
de:{latest:{title:'SAISONREGELN · ÜBERBLICK DER NEUEN SAISON',sections:[['Gebietstypen',['Außenposten verbinden Lagergebiete und schieben die Front vor; sie produzieren kein Mithril.','Festungen sind Hauptziele und produzieren wöchentlich Mithril.','Altäre sind hochwertige Gebiete und ab Woche 6 umkämpfbar.']],['Gebietseroberung',['Capture Tiles, Shelter Value, Portal Points und das alte Stronghold-System entfallen.','Vorrücken: Außenposten → Festungen → Altäre.','Offensiven und Kriege verbrauchen Versuche.','Hauptfenster täglich 12:00–13:00 Serverzeit; Dienstag und Donnerstag gibt es zusätzliche Fenster.','Altäre öffnen am Donnerstag der 6. Woche.','Gebiete können nicht freiwillig aufgegeben werden.','Gebiete anderer Allianzen desselben Lagers dürfen verstärkt, aber nicht angegriffen werden.']],['Zerstörung',['Eine gehaltene Festung wird dauerhaft zerstört, wenn ihre Haltbarkeit auf 0 fällt.','Der Angreifer erhält Mithril; die zerstörte Festung produziert keine Wochenbelohnungen mehr.','Ruinen können keinen Krieg erklären und zerstörte Gebiete erlauben keine Teleportation.']],['Neue Pässe',['Pässe dienen nur als Kartenübergänge. Geschlossen können keine Truppen passieren.','Geöffnet dürfen alle Lagermitglieder passieren, außer Camp-Pässen, die nur dem passenden Lager offenstehen.','Ist ein Pass geschlossen, können Anführer keine Offensive hindurch starten.']],['Teleportation',['Mitglieder desselben Lagers dürfen in von ihrem Lager eroberte Gebiete umziehen.','Eigenes Allianzgebiet: 1 Allianz-Teleporter. Gebiet einer anderen Allianz desselben Lagers: 1 Fortgeschrittener Teleporter.','Nach Angriff/Krieg ist bei erfüllten Bedingungen eine direkte Teleportation zum Ziel möglich.','Sondergebiete werden erst mit dem entsprechenden Spielinhalt verfügbar.','Zu einer zerstörten Festung kann nicht teleportiert werden.']]]},rules:{title:'WICHTIGE SAISON-6-REGELN',sections:[['Wachturmschutz',['Wachtürme in verbündetem Gebiet sind normalerweise geschützt.','Dienstag und Donnerstag von 12:00–13:00 wird der Schutz vorübergehend deaktiviert; nicht verbündete Allianzen können angreifen.','Öffnungs- und Passregeln gelten weiterhin.']],['Brennendes Feld',['Teleportierst du, während ein Wachturm Rallye-Ziel, im Kampf oder auf 0 Haltbarkeit ist, brennt das Ausgangsfeld und Teleportation wird gesperrt.','Feuerdauer: 1 Minute.','Im Temple-Contest-Gebiet gibt es keinen Status „brennendes Feld“.']],['Handelsposten kehren zurück',['Bekannte Handelsrouten öffnen wieder. Erobert Handelsposten, kontrolliert den Handelsfluss und erhaltet Belohnungen.']],['Temple Contest',['Die Götter öffnen uralte Tempel und Lager kämpfen um die Kontrolle.','Eroberungsfortschritt entscheidet die Kontrolle; Ranglisten vergeben Mithril.','Kills erhöhen die Schlachtfeldwertung und schalten Stufenbelohnungen frei.','Nach dem Event werden Segnungstruhen vergeben.']],['Uraltes Relikt',['Das Artefakt der Ursprungsländer hat den Großteil seiner Macht verloren. Sammelt Runen für Upgrades.','Bestimmte Stufen schalten Formationen frei; stärkere Helden verbessern die Werte.','Der Reliktfortschritt wird am Saisonende zurückgesetzt.']]]},buildings:{title:'SAISON-GEBÄUDESTRATEGIE',sections:[['Ziel',['Heiliges Wasser maximieren und Gebäude so früh wie möglich freischalten.']],['Phase 1 · Alles freischalten',['Obelisk hat immer Priorität.','Altar I → 15, II → 15, III → 15, dann IV freischalten.','Nicht einen Altar auf 30 bringen, bevor die nächsten freigeschaltet sind. Früher mehr Altäre = mehr Heiliges Wasser.']],['Phase 2 · Altäre gleichmäßig leveln',['16/16/16/16 → 17/17/17/17 usw. bis 30.','Jede Stufe bringt +720 Heiliges Wasser/Stunde; gleichmäßiges Leveln liefert den besten Gesamtdurchsatz.']],['Obelisk-Priorität',['Obelisk immer verbessern, sobald möglich: Er schaltet Gebäudestufen, neue Strukturen und Fortschritt frei.']],['Nach Obelisk 30',['Priorität: Portal zuerst, Heiligtum danach, Sammelgebäude zuletzt.']]]}},
es:{latest:{title:'GUÍA DE REGLAS DE TEMPORADA · RESUMEN DE LA NUEVA TEMPORADA',sections:[['Tipos de territorio',['Los Puestos avanzados conectan territorios del campamento y hacen avanzar el frente; no producen Mithril.','Las Fortalezas son los objetivos principales y producen Mithril cada semana.','Los Altares son territorios de gran valor y pueden disputarse desde la semana 6.']],['Conquista territorial',['Desaparecen las Capture Tiles, Shelter Value, Portal Points y el antiguo sistema Stronghold.','Progresa Puestos avanzados → Fortalezas → Altares.','Las ofensivas y guerras consumen intentos.','Ventana principal diaria 12:00–13:00 hora del servidor, con ventanas adicionales martes y jueves.','Los Altares se abren el jueves de la semana 6.','No se puede abandonar territorio voluntariamente.','Puedes reforzar territorios de otras alianzas del mismo campamento, pero no atacarlas.']],['Destrucción',['Una fortaleza controlada queda destruida permanentemente si su durabilidad llega a 0.','El atacante recibe Mithril; la fortaleza destruida deja de producir recompensas semanales.','Las ruinas no pueden declarar guerra y las zonas destruidas no permiten teletransporte.']],['Nuevos pasos',['Los pasos solo sirven para atravesar el mapa. Cerrados, ninguna tropa puede pasar.','Abiertos, todos los miembros del campamento pueden pasar, salvo los Camp Pass reservados al campamento correspondiente.','Con un paso cerrado, los líderes no pueden iniciar ofensivas a través de él.']],['Teletransporte',['Los miembros del mismo campamento pueden trasladarse a territorios capturados por su campamento.','Territorio de tu alianza: 1 Teletransportador de alianza. Territorio de otra alianza del mismo campamento: 1 Teletransportador avanzado.','Tras ataque/guerra, puedes teletransportarte directamente al objetivo cuando se cumplan las condiciones.','Las zonas especiales se habilitan según avance el contenido.','No se puede teletransportar a una fortaleza destruida.']]]},rules:{title:'REGLAS IMPORTANTES DE LA TEMPORADA 6',sections:[['Protección de la torre de vigilancia',['Las torres de vigilancia en territorio aliado están protegidas normalmente.','Martes y jueves de 12:00–13:00 la protección se desactiva temporalmente, permitiendo ataques de alianzas no aliadas.','Siguen aplicándose las reglas de apertura y pasos.']],['Casilla en llamas',['Si te teletransportas mientras una torre de vigilancia es objetivo de rally, está en combate o tiene 0 de durabilidad, la casilla de origen arde y se bloquea el teletransporte.','El fuego dura 1 minuto.','No existe el estado de casilla en llamas dentro del área Temple Contest.']],['Regreso del Puesto comercial',['Reabren las rutas comerciales habituales. Captura puestos, controla el flujo comercial y recibe recompensas.']],['Temple Contest',['Los dioses abren templos antiguos y los campamentos compiten por controlarlos.','El progreso de captura decide el control; las clasificaciones otorgan Mithril.','Las bajas aumentan la puntuación del campo y desbloquean recompensas por nivel.','Tras el evento se entregan cofres de bendición.']],['Reliquia antigua',['El artefacto de las Tierras de Origen perdió gran parte de su poder. Reúne Runas para mejorarlo.','Ciertos niveles desbloquean Formaciones; héroes más fuertes mejoran las estadísticas.','El progreso de la reliquia se reinicia al terminar la temporada.']]]},buildings:{title:'ESTRATEGIA DE EDIFICIOS DE TEMPORADA',sections:[['Objetivo',['Maximizar el Agua Sagrada y desbloquear edificios lo antes posible.']],['Fase 1 · Desbloquear todo',['El Obelisco siempre tiene prioridad.','Altar I → 15, II → 15, III → 15 y después desbloquea IV.','No subas un solo altar a 30 antes de desbloquear los siguientes. Más altares pronto = más Agua Sagrada.']],['Fase 2 · Subir todos los altares por igual',['16/16/16/16 → 17/17/17/17, etc., hasta 30.','Cada nivel añade +720 Agua Sagrada/hora; subirlos por igual ofrece el mejor rendimiento total.']],['Prioridad del Obelisco',['Mejora el Obelisco siempre que sea posible: desbloquea niveles de edificios, nuevas estructuras y progreso.']],['Después de Obelisco 30',['Prioridad: Portal primero, Santuario después y edificios de recolección al final.']]]}},
tr:{latest:{title:'SEZON KURALLARI REHBERİ · YENİ SEZON ÖZETİ',sections:[['Bölge Türleri',['Karakollar kamp bölgelerini bağlar ve cepheyi ilerletir; Mithril üretmez.','Kaleler ana hedeflerdir ve haftalık Mithril üretir.','Sunaklar yüksek değerli bölgelerdir ve 6. haftadan itibaren çekişmeye açılır.']],['Bölge Zaferi',['Capture Tile, Shelter Value, Portal Point ve eski Stronghold sistemi kaldırılmıştır.','İlerleme sırası: Karakol → Kale → Sunak.','Taarruz ve savaşlar deneme hakkı tüketir.','Ana pencere her gün sunucu saatiyle 12:00–13:00; salı ve perşembe ek pencereler vardır.','Sunaklar 6. haftanın perşembe günü açılır.','Bölge gönüllü olarak terk edilemez.','Aynı kamptaki başka ittifakların bölgelerine takviye gönderebilirsiniz ancak aynı kamp ittifakına saldıramazsınız.']],['Yıkım',['Sahip olunan bir kalenin dayanıklılığı 0 olursa kalıcı olarak yıkılır.','Saldıran taraf Mithril alır; yıkılan kale haftalık üretim yapmaz.','Harabeler savaş ilan edemez ve yıkılan bölgeye ışınlanılamaz.']],['Yeni Geçitler',['Geçitler yalnızca harita geçişidir. Kapalıyken birlikler geçemez.','Açıkken, yalnızca ilgili kampa özel Camp Pass hariç tüm kamp üyeleri geçebilir.','Geçit kapalıyken yöneticiler karşı tarafa taarruz başlatamaz.']],['Işınlanma',['Aynı kamp üyeleri kamplarının ele geçirdiği bölgelere taşınabilir.','Kendi ittifak bölgeniz: 1 İttifak Işınlayıcısı. Aynı kamptaki başka ittifak bölgesi: 1 Gelişmiş Işınlayıcı.','Saldırı/savaş sonrası koşullar uygunsa doğrudan hedefe ışınlanabilirsiniz.','Özel alanlar ilgili içerik açıldığında kullanılabilir.','Yıkılmış kaleye ışınlanılamaz.']]]},rules:{title:'SEZON 6 ÖNEMLİ KURALLARI',sections:[['Gözetleme Kulesi Koruması',['Dost bölgedeki gözetleme kuleleri normalde korumalıdır.','Salı ve perşembe 12:00–13:00 arasında koruma geçici olarak kalkar ve müttefik olmayan ittifaklar saldırabilir.','Açılış ve geçit kuralları yine geçerlidir.']],['Yanan Kare',['Gözetleme kulesi ralli hedefiyken, savaş halindeyken veya dayanıklılığı 0 iken ışınlanırsanız çıkış kareniz yanar ve ışınlanma engellenir.','Yangın 1 dakika sürer.','Temple Contest alanında yanan kare durumu uygulanmaz.']],['Ticaret Noktaları Geri Dönüyor',['Bilinen ticaret rotaları yeniden açılır. Ticaret noktalarını ele geçir, akışı kontrol et ve ödül kazan.']],['Temple Contest',['Tanrılar antik tapınakları açar ve kamplar kontrol için yarışır.','Ele geçirme ilerlemesi kontrolü belirler; sıralama Mithril ödülü verir.','Öldürmeler savaş alanı puanını artırır ve kademe ödüllerini açar.','Etkinlik sonrası kutsama sandıkları dağıtılır.']],['Antik Kalıntı',['Origin Lands eseri gücünün çoğunu kaybetmiştir. Rün toplayarak geliştir.','Belirli seviyeler Formasyonları açar; daha güçlü kahramanlar daha iyi istatistik verir.','Kalıntı ilerlemesi sezon sonunda sıfırlanır.']]]},buildings:{title:'SEZON BİNA STRATEJİSİ',sections:[['Hedef',['Kutsal Su üretimini en üst düzeye çıkar ve binaları mümkün olan en erken zamanda aç.']],['Aşama 1 · Her şeyi aç',['Dikilitaş her zaman önceliklidir.','Sunak I → 15, II → 15, III → 15, sonra IV’ü aç.','Sonrakileri açmadan tek bir sunağı 30’a çıkarma. Erken daha çok sunak = daha çok Kutsal Su.']],['Aşama 2 · Sunakları eşit yükselt',['16/16/16/16 → 17/17/17/17 şeklinde 30’a kadar devam et.','Her seviye +720 Kutsal Su/saat sağlar; eşit yükseltme en iyi toplam verimi verir.']],['Dikilitaş Önceliği',['Mümkün olduğunda Dikilitaşı yükselt; bina seviyelerini, yeni yapıları ve ilerlemeyi açar.']],['Dikilitaş 30 Sonrası',['Öncelik: önce Portal, sonra Tapınak, en son Toplama binaları.']]]}},
it:{latest:{title:'GUIDA ALLE REGOLE DI STAGIONE · PANORAMICA NUOVA STAGIONE',sections:[['Tipi di territorio',['Gli Avamposti collegano i territori del campo e fanno avanzare il fronte; non producono Mithril.','Le Fortezze sono gli obiettivi principali e producono Mithril ogni settimana.','Gli Altari sono territori di alto valore e diventano contendibili dalla settimana 6.']],['Conquista dei territori',['Non esistono più Capture Tile, Shelter Value, Portal Point e il vecchio sistema Stronghold.','Avanzamento: Avamposti → Fortezze → Altari.','Offensive e guerre consumano tentativi.','Finestra principale ogni giorno 12:00–13:00 ora server, con finestre aggiuntive martedì e giovedì.','Gli Altari aprono giovedì della settimana 6.','Un territorio non può essere abbandonato volontariamente.','Puoi rinforzare territori di altre alleanze dello stesso campo, ma non attaccare alleanze dello stesso campo.']],['Distruzione',['Una fortezza posseduta viene distrutta definitivamente quando la sua durabilità arriva a 0.','L’attaccante riceve Mithril; la fortezza distrutta non produce più ricompense settimanali.','Le rovine non possono dichiarare guerra e l’area distrutta non consente il teletrasporto.']],['Nuovi passi',['I passi servono solo ad attraversare la mappa. Quando sono chiusi, le truppe non possono passare.','Quando sono aperti, tutti i membri del campo possono passare, tranne i Camp Pass riservati al campo corrispondente.','Quando un passo è chiuso, i leader non possono lanciare offensive attraverso di esso.']],['Teletrasporto',['I membri dello stesso campo possono trasferirsi nei territori conquistati dal proprio campo.','Territorio della propria alleanza: 1 Teletrasportatore Alleanza. Territorio di un’altra alleanza dello stesso campo: 1 Teletrasportatore Avanzato.','Dopo attacco/guerra puoi teletrasportarti direttamente sul bersaglio quando le condizioni lo consentono.','Le aree speciali diventano disponibili con l’apertura dei relativi contenuti.','Non è possibile teletrasportarsi su una fortezza distrutta.']]]},rules:{title:'REGOLE IMPORTANTI DELLA STAGIONE 6',sections:[['Protezione Torre di Guardia',['Le torri di guardia nei territori alleati sono normalmente protette.','Martedì e giovedì dalle 12:00 alle 13:00 la protezione viene temporaneamente disattivata e le alleanze non alleate possono attaccare.','Restano valide le regole di apertura e dei passaggi.']],['Casella in fiamme',['Se ti teletrasporti mentre una torre di guardia è bersaglio di un rally, è in battaglia o ha durabilità 0, la casella di origine prende fuoco e il teletrasporto viene bloccato.','Il fuoco dura 1 minuto.','Nell’area Temple Contest non si applica lo stato di casella in fiamme.']],['Ritorno del Centro commerciale',['Le consuete rotte commerciali riaprono. Conquista i centri commerciali, controlla il flusso e ottieni ricompense.']],['Temple Contest',['Gli dei aprono antichi templi e i campi competono per il controllo.','Il progresso di cattura determina il controllo; le classifiche assegnano Mithril.','Le eliminazioni aumentano il punteggio del campo di battaglia e sbloccano ricompense a livelli.','Dopo l’evento vengono distribuiti forzieri benedizione.']],['Reliquia antica',['L’artefatto delle Terre d’Origine ha perso gran parte del suo potere. Raccogli Rune per potenziarlo.','Determinati livelli sbloccano Formazioni; eroi più forti forniscono statistiche migliori.','Il progresso della reliquia viene azzerato alla fine della stagione.']]]},buildings:{title:'STRATEGIA EDIFICI DI STAGIONE',sections:[['Obiettivo',['Massimizzare l’Acqua Sacra e sbloccare gli edifici il prima possibile.']],['Fase 1 · Sblocca tutto',['Obelisco sempre prioritario.','Altare I → 15, II → 15, III → 15, poi sblocca IV.','Non portare un solo altare a 30 prima di sbloccare i successivi. Più altari prima = più Acqua Sacra.']],['Fase 2 · Porta gli altari allo stesso livello',['16/16/16/16 → 17/17/17/17 e così via fino a 30.','Ogni livello aggiunge +720 Acqua Sacra/ora; livelli uniformi danno la migliore resa totale.']],['Priorità Obelisco',['Migliora l’Obelisco appena possibile: sblocca livelli edifici, nuove strutture e progressione.']],['Dopo Obelisco 30',['Priorità: prima Portale, poi Santuario, edifici di raccolta per ultimi.']]]}},
id:{latest:{title:'PANDUAN ATURAN SEASON · IKHTISAR SEASON BARU',sections:[['Jenis Wilayah',['Outpost menghubungkan wilayah kamp dan mendorong garis depan; tidak menghasilkan Mithril.','Fortress adalah objektif utama dan menghasilkan Mithril setiap minggu.','Altar adalah wilayah bernilai tinggi dan dapat diperebutkan mulai Minggu 6.']],['Kemenangan Wilayah',['Capture Tile, Shelter Value, Portal Point, dan sistem Stronghold lama sudah tidak digunakan.','Urutan maju: Outpost → Fortress → Altar.','Offensive dan war menggunakan kesempatan percobaan.','Jendela utama setiap hari pukul 12:00–13:00 waktu server, dengan jendela tambahan Selasa dan Kamis.','Altar dibuka Kamis pada Minggu 6.','Wilayah tidak dapat ditinggalkan secara sukarela.','Anda dapat memperkuat wilayah aliansi lain dalam kamp yang sama, tetapi tidak dapat menyerang aliansi satu kamp.']],['Penghancuran',['Fortress milik sendiri yang durability-nya mencapai 0 akan hancur permanen.','Penyerang mendapat Mithril; fortress yang hancur tidak lagi menghasilkan hadiah mingguan.','Reruntuhan tidak dapat menyatakan perang dan area yang hancur tidak dapat menjadi tujuan teleport.']],['Pass Baru',['Pass hanya berfungsi sebagai jalur peta. Saat tertutup, pasukan tidak dapat lewat.','Saat terbuka, semua anggota kamp dapat lewat, kecuali Camp Pass yang hanya untuk kamp terkait.','Saat pass tertutup, pemimpin tidak dapat meluncurkan offensive melintasinya.']],['Teleport',['Anggota kamp yang sama dapat pindah ke wilayah yang direbut oleh kampnya.','Wilayah aliansi sendiri: 1 Alliance Teleporter. Wilayah aliansi lain satu kamp: 1 Advanced Teleporter.','Setelah attack/war, Anda dapat teleport langsung ke target jika syarat terpenuhi.','Area khusus baru tersedia ketika konten terkait dibuka.','Tidak dapat teleport ke fortress yang sudah hancur.']]]},rules:{title:'ATURAN PENTING SEASON 6',sections:[['Perlindungan Watchtower',['Watchtower di wilayah sekutu biasanya dilindungi.','Selasa dan Kamis pukul 12:00–13:00 perlindungan sementara dinonaktifkan sehingga aliansi non-sekutu dapat menyerang.','Aturan pembukaan dan pass tetap berlaku.']],['Petak Terbakar',['Jika Anda teleport saat watchtower menjadi target rally, sedang bertempur, atau durability 0, petak asal terbakar dan teleport diblokir.','Api berlangsung 1 menit.','Status petak terbakar tidak berlaku di area Temple Contest.']],['Trade Post Kembali',['Rute perdagangan yang familiar dibuka kembali. Rebut Trade Post, kuasai arus perdagangan, dan dapatkan hadiah.']],['Temple Contest',['Para dewa membuka kuil kuno dan kamp bersaing untuk menguasainya.','Progres capture menentukan penguasaan; peringkat memberikan Mithril.','Kill meningkatkan rating medan perang dan membuka hadiah tingkat.','Blessing chest diberikan setelah event.']],['Ancient Relic',['Artefak Origin Lands kehilangan sebagian besar kekuatannya. Kumpulkan Rune untuk meningkatkan levelnya.','Level tertentu membuka Formation; hero yang lebih kuat memberikan statistik lebih baik.','Progres relic direset saat season berakhir.']]]},buildings:{title:'STRATEGI BANGUNAN SEASON',sections:[['Tujuan',['Maksimalkan produksi Holy Water dan buka bangunan secepat mungkin.']],['Fase 1 · Buka semuanya',['Obelisk selalu menjadi prioritas.','Altar I → 15, II → 15, III → 15, lalu buka IV.','Jangan menaikkan satu altar ke 30 sebelum membuka altar berikutnya. Lebih banyak altar sejak awal = lebih banyak Holy Water.']],['Fase 2 · Naikkan altar secara merata',['16/16/16/16 → 17/17/17/17 dan seterusnya sampai 30.','Setiap level menambah +720 Holy Water/jam; level yang merata memberi throughput total terbaik.']],['Prioritas Obelisk',['Upgrade Obelisk kapan pun memungkinkan: membuka level bangunan, struktur baru, dan progres.']],['Setelah Obelisk 30',['Prioritas: Portal paling dulu, Sanctuary berikutnya, bangunan Gathering terakhir.']]]}}
});

